import nbformat as nbf
nb = nbf.v4.new_notebook(); c = []
md = lambda s: c.append(nbf.v4.new_markdown_cell(s)); code = lambda s: c.append(nbf.v4.new_code_cell(s))
md("# Leakage-free preprocessing and evaluation: Rwanda malaria risk (DHS MIS 2023)\nRun top to bottom from the `notebooks/` folder. All statistics and transformers are fit on the training split only.")
code("import sys, warnings, json\nsys.path.insert(0, '..')\nwarnings.filterwarnings('ignore')\nimport pandas as pd, numpy as np\nfrom IPython.display import Image, display\nfrom src import data as D\nfrom src.pipeline_builder import split_train_test, make_preprocessor_for\nfrom src.diagnostics import run_diagnostics\nfrom src.evaluation import run_evaluation\nimport os; os.chdir('..')")
md("## 1. Load data and verify the initial N x P")
code("r = D.load_mis2023('data/raw/mis2023'); data, F = r['data'], r['feature_columns']\nN0, P0 = len(data), len(F)\nprint('Initial N x P =', N0, 'x', P0, '| overall positives:', int(data.y.sum()), f'({data.y.mean()*100:.2f}%)')")
md("## 2. Cluster-grouped, label-stratified split (no cluster appears in both sets)")
code("train, test = split_train_test(data)\nprint('seed', train.attrs.get('split_seed'), '| train', train.shape, int(train.y.sum()), '| test', test.shape, int(test.y.sum()))\nprint('cluster overlap:', len(set(train.cluster) & set(test.cluster)))\nassert not set(train.cluster) & set(test.cluster)")
md("## 3. Fit preprocessing on X_train only, apply to X_test")
code("prep, groups, num = make_preprocessor_for(train[F], F)\nZtr = prep.fit_transform(train[F]); Zte = prep.transform(test[F])\nprint('Final N x P (train):', Ztr.shape, '| (test):', Zte.shape)\nprint('NaNs train/test:', int(Ztr.isna().sum().sum()), int(Zte.isna().sum().sum()))\nprint('Initial', (N0, P0), '-> final train+test rows', len(Ztr)+len(Zte), 'x', Ztr.shape[1])\nassert list(Ztr.columns) == list(Zte.columns)\nprint({k: len(v) for k, v in groups.items() if isinstance(v, list)})")
md("## 4. Diagnostics and the eight figures (training data only)")
code("stats = run_diagnostics(train, F, figures_dir='figures', stats_path='reports/diagnostic_stats.json', test=test)\nprint('Little MCAR:', stats['littles_mcar'])\nprint('Cramer V (hml4 missing):', stats['cramers_v_missing_hml4'])\nprint('PCA k90/k95:', stats['pca']['k90'], stats['pca']['k95'])\nprint('pairs |r|>=0.85:', len(stats['collinear_pairs_r_ge_0.85']))")
code("for f in ['fig1_1_missingness_heatmap','fig1_2_target_distribution','fig2_1_outlier_boxplots','fig3_1_correlation_matrix','fig3_2_collinear_scatterplots','fig3_3_target_importance','fig4_1_transformation_grid','fig5_1_pca_scree_plot']:\n    display(Image(f'figures/{f}.png', width=800))")
md("## 5. Save processed matrices (git-ignored)")
code("os.makedirs('data/processed', exist_ok=True)\nZtr.assign(y=train.y.values, cluster=train.cluster.values, weight=train.weight.values).to_parquet('data/processed/train.parquet') if False else None\nZtr.to_csv('data/processed/X_train.csv', index=False); Zte.to_csv('data/processed/X_test.csv', index=False)\nprint('saved')")
md("## 6. Model comparison: grouped out-of-fold CV, calibration, weighted and unweighted metrics")
code("res, preds = run_evaluation(train, test, F, n_boot=200)\nrows = []\nfor m, e in res['models'].items():\n    for v in ['raw', 'platt']:\n        t = e['test'][v]\n        rows.append({'model': m, 'probs': v, 'PR-AUC': t['unweighted']['pr_auc'], 'PR-AUC (w)': t['weighted']['pr_auc'], 'ROC-AUC': t['unweighted']['roc_auc'], 'Brier': t['unweighted']['brier'], 'recall': t['unweighted']['recall'], 'precision': t['unweighted']['precision']})\nprint('baseline PR-AUC (prevalence):', round(res['baseline_pr_auc'], 4))\ndisplay(pd.DataFrame(rows).round(4))")
md("## 7. Improved evaluation: pooled out-of-fold results over all 179 positives")
code("from src.pooled import pooled_cv, HOUSEHOLD\nhh = [c for c in F if c in HOUSEHOLD]\nrows = []\nfor name, feats, cm in [('A all features', F, False), ('B household', hh, False), ('C household + cluster means', hh, True)]:\n    res_p, _ = pooled_cv('logistic', data, feats, cluster_means=cm)\n    rows.append({'config': name, 'PR-AUC': res_p['pr_auc'], 'ROC-AUC': res_p['roc_auc'], 'lift@20%': res_p['lift_top20pct'], 'Brier (Platt)': res_p['brier_platt']})\nprint('baseline PR-AUC', round(data.y.mean(), 4))\ndisplay(pd.DataFrame(rows).round(4))")
md("## 8. Interview-month climate features (CHIRPS v3, ERA5-Land dewpoint, MODIS EVI/NDVI)\nTested as a possible improvement. Results are read from the saved evaluation (`python -m src.pooled_dynamic` regenerates them); they do not beat configuration C.")
code("import json\nd = json.load(open('reports/pooled_dynamic_evaluation.json'))\nrows = [{'config': k, 'model': m, 'PR-AUC': r['pr_auc'], 'ROC-AUC': r['roc_auc'], 'lift@20%': r['lift_top20pct']} for k, v in d['configs'].items() for m, r in v.items()]\nprint('baseline PR-AUC', round(d['baseline_pr_auc'], 4), '| dynamic features:', len(d['dynamic_features']))\ndisplay(pd.DataFrame(rows).round(4))")
md("## 9. Improvement path\nBaseline 0.0096 -> hold-out best 0.0203 -> pooled all features 0.0211 -> household only 0.0408 -> household + cluster means **0.0498** (retained) -> adding interview-month climate 0.0194 (rejected).")
nb.cells = c; nbf.write(nb, 'notebooks/pipeline_execution.ipynb')
